"""The analytics event catalog as each runtime's `Event` enum: server and agent Python, dashboard TypeScript."""

from __future__ import annotations

import json
import textwrap

from ..analytics import CatalogEvent, CatalogGroup, EventCatalog, Runtime
from ..probe_contracts import Contracts
from .typescript import member_key

SOURCE = "contracts/probe_contracts/analytics/events.json"
WIDTH = 100

_PY_HEADER = (
    f"# GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "# Do not edit: change the catalog there and rerun.\n"
)
_TS_HEADER = (
    f"// GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "// Do not edit: change the catalog there and rerun.\n"
)

_SERVER_DOC = (
    "Every product event the server names: `track(Event.SEARCH_PERFORMED, ...)`. A member equals "
    "its wire name; values never change. PostHog-only: a domain lifecycle event is an `EventType` "
    "(app/shared/event_log.py), which `record_event` writes to the tenant `events` table and "
    "forwards. A name lands here when its surface is a read or unauthenticated, or lives in the "
    "control database, where `record_event` cannot write."
)
_AGENT_DOC = (
    "Every product event name the CLI, SDK, daemon, service and MCP send: "
    "`track(Event.OUTBOX_STUCK, ...)`. A member equals its wire string, so it and its EVENT_* "
    "constant are interchangeable; values never change."
)
_DASHBOARD_DOC = (
    "Every custom browser event: `track(Event.ShareDialogOpened, props)`. Viewer-attributed, "
    "unlike the server's team-attributed events. Values are wire names and never change."
)


def _wrap(text: str, prefix: str) -> str:
    """`text` as comment lines starting with `prefix`, within WIDTH."""
    if not text:
        return ""
    lines = textwrap.wrap(text, WIDTH - len(prefix), break_long_words=False, break_on_hyphens=False)
    return "".join(f"{prefix}{line}\n" for line in lines)


def _render_python_group(group: CatalogGroup, first: bool) -> str:
    out = "" if first else "\n"
    out += f"    # --- {group.title} ---\n" + _wrap(group.doc, "    # ")
    for event in group.events:
        out += _wrap(event.doc, "    #: ") + f"    {event.key} = {json.dumps(event.name)}\n"
    return out


def render_python_events(catalog: EventCatalog, runtime: Runtime, *, str_enum: str, doc: str) -> str:
    groups = catalog.get_groups(runtime)
    body = "".join(_render_python_group(group, i == 0) for i, group in enumerate(groups))
    docstring = textwrap.fill(doc, WIDTH - 4, initial_indent="    ", subsequent_indent="    ",
                              break_long_words=False, break_on_hyphens=False)
    return (
        _PY_HEADER
        + f'"""The {runtime} runtime\'s product-analytics events (probe-contracts\' catalog)."""\n\n'
        + "from __future__ import annotations\n\n"
        + f"{str_enum}\n\n\n"
        + "class Event(StrEnum):\n"
        + f'    """{docstring.strip()}\n    """\n\n'
        + body
    )


def render_server_events(contracts: Contracts) -> str:
    return render_python_events(contracts.events, Runtime.SERVER, str_enum="from enum import StrEnum",
                                doc=_SERVER_DOC)


def render_agent_events(contracts: Contracts) -> str:
    # 3.11's StrEnum, kept for 3.10 by the SDK (agent/tests/test_py310_compat.py).
    return render_python_events(contracts.events, Runtime.AGENT,
                                str_enum="from probe.foundation.compat.compat import StrEnum",
                                doc=_AGENT_DOC)


def _render_ts_doc(event: CatalogEvent) -> str:
    if not event.doc:
        return ""
    lines = textwrap.wrap(event.doc, WIDTH - 6, break_long_words=False, break_on_hyphens=False)
    if len(lines) == 1 and len(lines[0]) <= WIDTH - 9:
        return f"  /** {lines[0]} */\n"
    return "  /**\n" + "".join(f"   * {line}\n" for line in lines) + "   */\n"


def render_dashboard_events(contracts: Contracts) -> str:
    groups = contracts.events.get_groups(Runtime.DASHBOARD)
    body = ""
    for i, group in enumerate(groups):
        body += ("" if i == 0 else "\n") + f"  // --- {group.title} ---\n" + _wrap(group.doc, "  // ")
        for event in group.events:
            body += _render_ts_doc(event) + f"  {member_key(event.key)}: {json.dumps(event.name)},\n"
    doc = "".join(f" * {line}\n" for line in textwrap.wrap(_DASHBOARD_DOC, WIDTH - 3))
    return (
        _TS_HEADER
        + "\n/**\n" + doc + " */\n"
        + "export const Event = {\n" + body + "} as const;\n\n"
        + "export type Event = (typeof Event)[keyof typeof Event];\n"
    )
